import{_ as a,o as n,c as i,ai as e}from"./chunks/framework.Duywnu3E.js";const o=JSON.parse('{"title":"10. Настройте инфраструктуру разрешения доменных имён для офисов HQ и BR:","description":"","frontmatter":{},"headers":[],"relativePath":"module1/task1-10.md","filePath":"module1/task1-10.md"}'),l={name:"module1/task1-10.md"};function p(t,s,h,r,c,d){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_10-настроите-инфраструктуру-разрешения-доменных-имен-для-офисов-hq-и-br" tabindex="-1">10. Настройте инфраструктуру разрешения доменных имён для офисов HQ и BR: <a class="header-anchor" href="#_10-настроите-инфраструктуру-разрешения-доменных-имен-для-офисов-hq-и-br" aria-label="Permalink to “10. Настройте инфраструктуру разрешения доменных имён для офисов HQ и BR:”">​</a></h1><details class="details custom-block"><summary>Details</summary><ul><li><p>Основной DNS-сервер реализован на HQ-SRV</p></li><li><p>Сервер должен обеспечивать разрешение имён в сетевые адреса устройств и обратно в соответствии с таблицей 3</p></li><li><p>В качестве DNS-сервера пересылки используйте любой общедоступный DNS-сервер (77.88.8.7, 77.88.8.3 или другие)</p></li></ul></details><p>В рамках руководства, будем придерживаться <a href="/sa-demo-wiki/appendix/ip_table.html">этой таблицы адресации</a>, <em><strong>чего и вам советуем, если вы слепо следуете руководству и не понимаете что делаете!</strong></em></p><p>Устанавливаем BIND на HQ-SRV.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bind-utils</span></span></code></pre></div><h2 id="_10-1-конфигурация-options-conf" tabindex="-1">10.1 Конфигурация options.conf <a class="header-anchor" href="#_10-1-конфигурация-options-conf" aria-label="Permalink to “10.1 Конфигурация options.conf”">​</a></h2><p>Редактируем файл <code>/etc/bind/options.conf</code>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Этот же файл доступен по пути <code>/var/lib/bind/etc/bind/options.conf</code>.</p></div><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-SRV</span></span>
<span class="line"><span># /etc/bind/options.conf</span></span>
<span class="line highlighted"><span>options {</span></span>
<span class="line highlighted"><span>    directory &quot;/etc/bind/zone&quot;;</span></span>
<span class="line highlighted"><span>    listen-on { 127.0.0.1; 192.168.100.0/28; };</span></span>
<span class="line highlighted"><span>    forwarders { 77.88.8.8; };</span></span>
<span class="line highlighted"><span>    recursion yes;</span></span>
<span class="line highlighted"><span>    allow-query { any; };</span></span>
<span class="line highlighted"><span>    dnssec-validation no;</span></span>
<span class="line highlighted"><span>};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="_10-2-конфигурация-зон" tabindex="-1">10.2 Конфигурация зон <a class="header-anchor" href="#_10-2-конфигурация-зон" aria-label="Permalink to “10.2 Конфигурация зон”">​</a></h2><p>Редактируем файл <code>/etc/bind/local.conf</code> для объявления прямой и обратной зон.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-SRV</span></span>
<span class="line"><span># /etc/bind/local.conf</span></span>
<span class="line highlighted"><span>zone &quot;au-team.irpo&quot; {</span></span>
<span class="line highlighted"><span>    type master;</span></span>
<span class="line highlighted"><span>    file &quot;au-team.irpo.db&quot;;</span></span>
<span class="line highlighted"><span>};</span></span>
<span class="line highlighted"><span></span></span>
<span class="line highlighted"><span>zone &quot;100.168.192.in-addr.arpa&quot; {</span></span>
<span class="line highlighted"><span>    type master;</span></span>
<span class="line highlighted"><span>    file &quot;100.168.192.in-addr.arpa.db&quot;;</span></span>
<span class="line highlighted"><span>};</span></span>
<span class="line highlighted"><span></span></span>
<span class="line highlighted"><span>zone &quot;200.168.192.in-addr.arpa&quot; {</span></span>
<span class="line highlighted"><span>    type master;</span></span>
<span class="line"><span>    file &quot;200.168.192.in-addr.arpa.db&quot;;</span></span>
<span class="line"><span>};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h2 id="_10-3-фаил-прямои-зоны" tabindex="-1">10.3 Файл прямой зоны <a class="header-anchor" href="#_10-3-фаил-прямои-зоны" aria-label="Permalink to “10.3 Файл прямой зоны”">​</a></h2><p>Создаём файл прямой зоны <code>/etc/bind/zone/au-team.irpo.db</code>.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-SRV</span></span>
<span class="line"><span># /etc/bind/zone/au-team.irpo.db</span></span>
<span class="line highlighted"><span>$TTL 1D</span></span>
<span class="line highlighted"><span>@       IN      SOA     hq-srv admin.au-team.irpo. (</span></span>
<span class="line highlighted"><span>                        2026042401      ; serial</span></span>
<span class="line highlighted"><span>                        1H              ; refresh</span></span>
<span class="line highlighted"><span>                        30M             ; retry</span></span>
<span class="line highlighted"><span>                        1W              ; expire</span></span>
<span class="line highlighted"><span>                        1D )            ; minimum</span></span>
<span class="line highlighted"><span>;</span></span>
<span class="line highlighted"><span></span></span>
<span class="line highlighted"><span>@       IN      NS      hq-srv.au-team.irpo.</span></span>
<span class="line highlighted"><span>hq-rtr  IN      A       192.168.100.1</span></span>
<span class="line highlighted"><span>hq-srv  IN      A       192.168.100.2</span></span>
<span class="line highlighted"><span>br-rtr  IN      A       192.168.3.1</span></span>
<span class="line highlighted"><span>br-srv  IN      A       192.168.3.2</span></span>
<span class="line highlighted"><span>hq-cli  IN      A       192.168.200.2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Конкретные записи (A-записи) и их IP-адреса должны соответствовать таблице 3 из задания. Сверьтесь с вашей таблицей адресации.</p></div><h2 id="_10-4-фаил-обратнои-зоны" tabindex="-1">10.4 Файл обратной зоны <a class="header-anchor" href="#_10-4-фаил-обратнои-зоны" aria-label="Permalink to “10.4 Файл обратной зоны”">​</a></h2><p>Создаём файл обратной зоны <code>/etc/bind/zone/100.168.192.in-addr.arpa.db</code>.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-SRV</span></span>
<span class="line"><span># /etc/bind/zone/100.168.192.in-addr.arpa.db</span></span>
<span class="line highlighted"><span>$TTL 1D</span></span>
<span class="line highlighted"><span>@       IN      SOA     hq-srv.au-team.irpo. admin.au-team.irpo. (</span></span>
<span class="line highlighted"><span>                        2026042401      ; serial</span></span>
<span class="line highlighted"><span>                        1H              ; refresh</span></span>
<span class="line highlighted"><span>                        30M             ; retry</span></span>
<span class="line highlighted"><span>                        1W              ; expire</span></span>
<span class="line highlighted"><span>                        1D )            ; minimum</span></span>
<span class="line highlighted"><span>;</span></span>
<span class="line highlighted"><span>@       IN      NS      hq-srv.au-team.irpo.</span></span>
<span class="line highlighted"><span>1       IN      PTR     hq-rtr.au-team.irpo.</span></span>
<span class="line highlighted"><span>2       IN      PTR     hq-srv.au-team.irpo.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h2 id="_10-5-применение-и-проверка" tabindex="-1">10.5 Применение и проверка <a class="header-anchor" href="#_10-5-применение-и-проверка" aria-label="Permalink to “10.5 Применение и проверка”">​</a></h2><p>Включаем и добавляем BIND в автозагрузку.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bind</span></span></code></pre></div><p>Проверяем корректность конфигурации.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">named-checkconf</span></span></code></pre></div><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">named-checkzone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> au-team.irpo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/bind/zone/au-team.irpo.db</span></span></code></pre></div><p>Проверяем разрешение имён.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HQ-SRV</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @127.0.0.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hq-srv.au-team.irpo</span></span></code></pre></div><p>Если в ответе присутствует правильный IP-адрес — DNS-сервер настроен корректно.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Не забудьте на всех машинах обновить <code>resolv.conf</code>, указав HQ-SRV в качестве DNS-сервера:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 192.168.100.2</span></span></code></pre></div></div>`,29)])])}const g=a(l,[["render",p]]);export{o as __pageData,g as default};
